from rest_framework import viewsets, permissions, serializers, renderers
from .models import CorporateProject, Milestone

class MilestoneSerializer(serializers.ModelSerializer):
    project = serializers.PrimaryKeyRelatedField(queryset=CorporateProject.objects.none())

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        request = self.context.get('request')
        if request and hasattr(request, 'user') and hasattr(request.user, 'client'):
            # Restrict selectable project choices strictly to user's client organization
            self.fields['project'].queryset = CorporateProject.objects.filter(client=request.user.client)

    class Meta:
        model = Milestone
        fields = ["id", "project", "title", "due_date", "budget_allocated"]

class MilestoneViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticated]
    serializer_class = MilestoneSerializer
    renderer_classes = [renderers.JSONRenderer, renderers.BrowsableAPIRenderer]

    def get_queryset(self):
        return Milestone.objects.filter(project__client=self.request.user.client)
